/* Proposed Sales-owned eligibility policy. Existing sales records are never modified. */
(function(){
function policy(){return state.salesPolicyPreview??={version:1,minWeight:35,tolerance:0.2,shareWeighing:true,rows:[{species:'Goat',breed:'Any breed',sex:'Male',enabled:true,minWeight:null,price:null},{species:'Sheep',breed:'Any breed',sex:'Female',enabled:false,minWeight:null,price:null}]};}
window.salesPolicyResult=function(p,a){const breed=value=>String(value||'').trim().toLowerCase();const candidates=p.rows.filter(r=>r.species===a.species&&r.sex===a.sex&&(breed(r.breed)==='any breed'||breed(r.breed)===breed(a.breed)));const row=candidates.find(r=>breed(r.breed)!=='any breed')||candidates[0];if(!row)return {eligible:false,reason:'No rule configured for this group'};if(!row.enabled)return {eligible:false,reason:'This group is not enabled for sale'};const min=row.minWeight==null?p.minWeight:row.minWeight,threshold=min-p.tolerance;return {eligible:a.weight>=threshold,threshold,reason:a.weight>=threshold?'Meets the configured minimum after tolerance':'Below the configured minimum after tolerance',price:row.price};};
window.openSalesPolicy=function(){const p=policy();modal('Sales eligibility and price settings',`<p>Proposed Sales settings for review. The existing Sales register, recorded prices and Weighing reporting thresholds stay separate.</p><div class="inputrow"><label class="field">Common minimum weight (kg)<input id="sp-min" type="number" min="0" step="0.1" value="${p.minWeight}" ${canEdit()?'':'disabled'}></label><label class="field">Allowed weighing difference (kg)<input id="sp-tolerance" type="number" min="0" step="0.01" value="${p.tolerance}" ${canEdit()?'':'disabled'}></label></div><p class="muted">Example: 35 kg with 0.2 kg allowance means 34.8 kg meets the weight check. Other approval and transaction checks still apply.</p><div class="tablewrap sales-policy-groups"><table><thead><tr><th>May sell</th><th>Species</th><th>Breed</th><th>Sex</th><th>Minimum kg<br>(blank = common)</th><th>Price ₹/kg<br>(blank = unset)</th></tr></thead><tbody>${p.rows.map((r,i)=>`<tr><td data-label="May sell"><input aria-label="Enable group ${i+1}" id="sp-on-${i}" type="checkbox" ${r.enabled?'checked':''} ${canEdit()?'':'disabled'}></td><td data-label="Species"><select aria-label="Species group ${i+1}" id="sp-species-${i}" ${canEdit()?'':'disabled'}>${['Goat','Sheep'].map(x=>`<option ${r.species===x?'selected':''}>${x}</option>`).join('')}</select></td><td data-label="Breed"><input aria-label="Breed group ${i+1}" id="sp-breed-${i}" value="${esc(r.breed)}" ${canEdit()?'':'disabled'}></td><td data-label="Sex"><select aria-label="Sex group ${i+1}" id="sp-sex-${i}" ${canEdit()?'':'disabled'}>${['Male','Female'].map(x=>`<option ${r.sex===x?'selected':''}>${x}</option>`).join('')}</select></td><td data-label="Minimum kg (blank = common)"><input aria-label="Minimum weight group ${i+1}" id="sp-weight-${i}" type="number" min="0" step="0.1" value="${r.minWeight??''}" ${canEdit()?'':'disabled'}></td><td data-label="Price ₹/kg (blank = unset)"><input aria-label="Price group ${i+1}" id="sp-price-${i}" type="number" min="0" step="0.01" value="${r.price??''}" ${canEdit()?'':'disabled'}></td></tr>`).join('')}</tbody></table></div><label class="checkrow"><input id="sp-sharing" type="checkbox" ${p.shareWeighing?'checked':''} ${canEdit()?'':'disabled'}>Use these eligibility rules in the Weighing preview</label><p id="sp-error" role="status"></p><div class="actions"><button onclick="salesPolicySave(true)" ${canEdit()?'':'disabled'}>Add another group</button><button class="primary" onclick="salesPolicySave(false)" ${canEdit()?'':'disabled'}>Save practice settings</button><button onclick="salesPolicyTry()">Try the saved rule</button></div><p class="muted">This local draft does not enforce live sales. Prices are proposed policy values, not completed sale amounts. Changes do not rewrite historical records.</p>`,true);};
window.salesPolicySave=function(add){if(!canEdit())return;const old=policy(),min=$('#sp-min'),tol=$('#sp-tolerance');let error='';const num=e=>{if(e.validity?.badInput||e.value.trim()===''||!Number.isFinite(Number(e.value))||Number(e.value)<0)error='Enter valid non-negative weights and prices; leave optional values blank if unset.';return Number(e.value)};const next={version:old.version+1,minWeight:num(min),tolerance:num(tol),shareWeighing:$('#sp-sharing').checked,rows:old.rows.map((r,i)=>({species:$('#sp-species-'+i).value,sex:$('#sp-sex-'+i).value,breed:$('#sp-breed-'+i).value.trim(),enabled:$('#sp-on-'+i).checked,minWeight:$('#sp-weight-'+i).value===''&&!$('#sp-weight-'+i).validity?.badInput?null:num($('#sp-weight-'+i)),price:$('#sp-price-'+i).value===''&&!$('#sp-price-'+i).validity?.badInput?null:num($('#sp-price-'+i))}))};if(next.tolerance>next.minWeight||next.rows.some(r=>r.minWeight!==null&&r.minWeight<next.tolerance))error='The allowance cannot exceed a minimum weight.';if(next.rows.some(r=>!r.breed))error='Enter a breed or use Any breed.';const keys=next.rows.map(r=>[r.species,r.breed.toLowerCase(),r.sex].join('|'));if(new Set(keys).size!==keys.length)error='Each species, breed and sex combination needs one rule.';if(error){$('#sp-error').textContent=error;return false;}if(add)next.rows.push({species:'Goat',breed:'New breed',sex:'Female',enabled:false,minWeight:null,price:null});state.salesPolicyPreview=next;persist();openSalesPolicy();toast('Practice Sales settings saved.');return true;};
window.salesPolicyTry=function(){const p=policy();modal('Try Sales eligibility',`<p>Saved practice policy ${p.version}. This test does not approve a sale.</p><div class="inputrow"><label class="field">Species<select id="sp-test-species"><option>Goat</option><option>Sheep</option></select></label><label class="field">Breed<input id="sp-test-breed" value="Example breed"></label><label class="field">Sex<select id="sp-test-sex"><option>Male</option><option>Female</option></select></label><label class="field">Weight (kg)<input id="sp-test-weight" type="number" step="0.1" value="34.8"></label></div><button class="primary" onclick="salesPolicyCheck()">Check this animal</button><p id="sp-test-result" role="status"></p>`);};
window.salesPolicyCheck=function(){const el=$('#sp-test-weight'),weight=Number(el.value);if(el.validity?.badInput||!el.value.trim()||!Number.isFinite(weight)||weight<0){$('#sp-test-result').textContent='Enter a valid weight.';return;}const r=salesPolicyResult(policy(),{species:$('#sp-test-species').value,breed:$('#sp-test-breed').value,sex:$('#sp-test-sex').value,weight});$('#sp-test-result').textContent=(r.eligible?'Meets weight rule. ':'Does not meet rule. ')+r.reason+(r.price!=null?' Proposed price ₹'+r.price+'/kg.':' No price configured.');};
const base=window.renderConsumerSurface;window.renderConsumerSurface=function(module,label){const result=base(module,label);const el=$('#content');if(result&&label==='Sales Config')el.insertAdjacentHTML('beforeend',`<section class="card"><h2>Eligibility and prices by animal group</h2><p>Set a common minimum and allowance, then choose which species, breeds and sexes may be sold and their proposed prices.</p><button onclick="openSalesPolicy()">Review proposed Sales settings</button><p class="muted">New configuration proposal; existing sale entries and valuation reports remain separate.</p></section>`);if(result&&label==='ADG Analytics')el.insertAdjacentHTML('beforeend',`<section class="card"><h2>Sales eligibility · shared settings</h2><p>${policy().shareWeighing?'Sales has shared its practice eligibility policy with this view. The reporting cards above still use their own reporting thresholds.':'Sales has not shared this practice policy with Weighing.'}</p>${policy().shareWeighing?'<button onclick="salesPolicyTry()">Try the shared Sales rule</button>':''}</section>`);return result;};
})();
